    private RuntimeRequesterContext resolveRequester(String t,String taskRef,String runId){String task=normalizeTaskRef(taskRef);if(blank(task))throw new IllegalArgumentException("PLAN_TASK_REF_REQUIRED_FOR_REQUESTER_CONTEXT");Map<String,Object> row=one("select origin_principal_type,origin_principal_id,requester_department_id,requester_group_id,sensitivity_level,site_id,plant_id,hop_count from tasks where tenant_id=:tenant and task_id=:id",t,task);String raw=str(row,"origin_principal_type"),pid=str(row,"origin_principal_id");if(blank(raw)||blank(pid))throw new IllegalArgumentException("TASK_ORIGIN_PRINCIPAL_PROVENANCE_REQUIRED");String type=mapPrincipalType(raw),dept=null;List<String> groups=List.of(),roles=List.of();if("HUMAN".equals(type)){validateHuman(t,pid);dept=currentPrimaryDepartment(t,pid);groups=currentGroups(t,pid);roles=currentRoles(t,"USER",pid,groups);}else if("SERVICE_ACCOUNT".equals(type)){Map<String,Object> sa=one("select status,owner_department_id from token_service_accounts where tenant_id=:tenant and service_account_id=:id",t,pid);if(!"ACTIVE".equals(str(sa,"status")))throw new IllegalArgumentException("SERVICE_ACCOUNT_NOT_ACTIVE");dept=str(sa,"owner_department_id");roles=currentRoles(t,"SERVICE_ACCOUNT",pid,List.of());}else if("AGENT".equals(type)){Map<String,Object> a=one("select approval_status,enabled,owner_department_id,owner_group_id from agent_profiles where tenant_id=:tenant and agent_id=:id",t,pid);if(!Boolean.TRUE.equals(a.get("enabled"))||!"APPROVED".equals(str(a,"approval_status")))throw new IllegalArgumentException("AGENT_NOT_CURRENTLY_APPROVED");dept=str(a,"owner_department_id");String g=str(a,"owner_group_id");groups=blank(g)?List.of():List.of(g);}else if(!"SYSTEM".equals(type))throw new IllegalArgumentException("UNSUPPORTED_RUNTIME_REQUESTER_PRINCIPAL_TYPE:"+raw);Integer calls=jdbc.queryForObject("select count(*) from plan_execution_attempts where tenant_id=:tenant and run_id=:run",new MapSqlParameterSource("tenant",t).addValue("run",runId),Integer.class);int depth=row.get("hop_count") instanceof Number n?n.intValue():0;return new RuntimeRequesterContext(type,pid,dept,groups,roles,first(str(row,"sensitivity_level"),"INTERNAL"),str(row,"site_id"),str(row,"plant_id"),Math.max(0,depth),calls==null?0:calls);}
    private void validateHuman(String t,String user){Integer c=jdbc.queryForObject("select count(*) from iam_users u join org_tenant_memberships m on m.user_id=u.user_id and m.tenant_id=:tenant where u.user_id=:id and u.status='ACTIVE' and m.status='ACTIVE' and (m.expires_at is null or m.expires_at>now())",new MapSqlParameterSource("tenant",t).addValue("id",user),Integer.class);if(c==null||c==0)throw new IllegalArgumentException("HUMAN_REQUESTER_NOT_CURRENTLY_ACTIVE");}
