    private List<String> currentGroups(String t,String user){return jdbc.queryForList("select group_id from org_group_memberships where tenant_id=:tenant and user_id=:id and status='ACTIVE' and effective_at<=now() and (expires_at is null or expires_at>now()) order by group_id",new MapSqlParameterSource("tenant",t).addValue("id",user),String.class);}
    private List<String> currentRoles(String t,String ptype,String pid,List<String> groups){LinkedHashSet<String> out=new LinkedHashSet<>();out.addAll(jdbc.queryForList("select distinct r.role_code from rbac_principal_role_bindings b join rbac_roles r on r.role_id=b.role_id where (b.tenant_id=:tenant or b.tenant_id is null) and b.principal_type=:ptype and b.principal_id=:pid and b.status='ACTIVE' and b.effective_at<=now() and (b.expires_at is null or b.expires_at>now()) and r.status='ACTIVE'",new MapSqlParameterSource("tenant",t).addValue("ptype",ptype).addValue("pid",pid),String.class));if("USER".equals(ptype)&&!groups.isEmpty())out.addAll(jdbc.queryForList("select distinct r.role_code from rbac_principal_role_bindings b join rbac_roles r on r.role_id=b.role_id where (b.tenant_id=:tenant or b.tenant_id is null) and b.principal_type='GROUP' and b.principal_id in (:groups) and b.status='ACTIVE' and b.effective_at<=now() and (b.expires_at is null or b.expires_at>now()) and r.status='ACTIVE'",new MapSqlParameterSource("tenant",t).addValue("groups",groups),String.class));return List.copyOf(out);}

