    private void bind(String t){IamTenantExecutionContext c=IamTenantContextHolder.current().orElse(null);if(c!=null&&!"INSTANCE".equalsIgnoreCase(c.tenantId())&&!t.equals(c.tenantId()))throw new IllegalArgumentException("Tenant context mismatch for Plan Admission");jdbc.getJdbcTemplate().queryForObject("select set_config('app.current_tenant_id', ?, true)",String.class,t);jdbc.getJdbcTemplate().queryForObject("select set_config('app.current_actor_id', ?, true)",String.class,actor());}
    private String actor(){IamTenantExecutionContext c=IamTenantContextHolder.current().orElse(null);return c==null||blank(c.actorId())?"plan-admission-runtime":c.actorId();}
    private String mapPrincipalType(String v){String x=upper(v);return switch(x){case "HUMAN","USER"->"HUMAN";case "SERVICE_ACCOUNT","MACHINE"->"SERVICE_ACCOUNT";case "AGENT"->"AGENT";case "SYSTEM"->"SYSTEM";default->x;};}
    private String normalizeTaskRef(String v){if(blank(v))return null;String x=v.trim();return x.startsWith("task:")?x.substring(5):x;}
    private String tenant(String v){return required(v,"tenantId");}private String required(String v,String f){if(blank(v))throw new IllegalArgumentException(f+" is required");return v.trim();}private boolean blank(String v){return v==null||v.isBlank();}private String first(String a,String b){return !blank(a)?a:b;}private String upper(String v){return blank(v)?"":v.trim().toUpperCase(Locale.ROOT);}private String policyStatus(String v){String x=upper(first(v,"DRAFT"));if(!POLICY_STATUS.contains(x))throw new IllegalArgumentException("Unsupported Plan Admission Policy status: "+x);return x;}private String normalizeSensitivity(String v){String x=upper(v);if(!SENSITIVITY.contains(x))throw new IllegalArgumentException("Unsupported sensitivity: "+x);return x;}private String normalizeSideEffect(String v){String x=upper(v);if(!SIDE_EFFECTS.contains(x))throw new IllegalArgumentException("Unsupported sideEffect: "+x);return x;}private int rankSensitivity(String v){int i=SENSITIVITY.indexOf(normalizeSensitivity(first(v,"INTERNAL")));return i<0?SENSITIVITY.size():i;}private int rankSide(String v){return switch(normalizeSideEffect(v)){case "NONE"->0;case "READ"->1;default->2;};}
    private List<String> normalizeSet(List<String> in,Set<String> allowed,String field){List<String> out=upperList(in);for(String v:out)if(!allowed.contains(v))throw new IllegalArgumentException(field+" contains unsupported value: "+v);return out;}private List<String> upperList(List<String> in){if(in==null)return List.of();return in.stream().filter(Objects::nonNull).map(this::upper).filter(s->!s.isBlank()).distinct().sorted().toList();}private List<String> trimList(List<String> in){if(in==null)return List.of();return in.stream().filter(Objects::nonNull).map(String::trim).filter(s->!s.isBlank()).distinct().sorted().toList();}private List<String> dedup(Collection<String> in){return in==null?List.of():in.stream().filter(Objects::nonNull).filter(s->!s.isBlank()).distinct().toList();}
    private Map<String,Object> one(String sql,String t,String id){try{return jdbc.queryForMap(sql,new MapSqlParameterSource("tenant",t).addValue("id",id));}catch(EmptyResultDataAccessException ex){throw new IllegalArgumentException("Referenced Plan Admission resource not found: "+id);}}private String str(Map<String,Object> m,String k){Object v=m.get(k);return v==null?null:String.valueOf(v);}private String write(Object v){try{return json.writeValueAsString(v);}catch(Exception e){throw new IllegalArgumentException("Plan Admission evidence cannot be serialized",e);}}private List<String> readStrings(String v){try{return blank(v)?List.of():json.readValue(v,STRING_LIST);}catch(Exception e){throw new IllegalStateException("Plan Admission list cannot be read",e);}}private Map<String,Object> readMap(String v){try{return blank(v)?Map.of():json.readValue(v,OBJECT_MAP);}catch(Exception e){throw new IllegalStateException("Plan Admission object cannot be read",e);}}private CapabilityRequirement readRequirement(String v){try{return json.readValue(v,CapabilityRequirement.class);}catch(Exception e){throw new IllegalStateException("CapabilityRequirement cannot be read",e);}}

