    private record FlowConstraint(List<String> allowedPools,List<String> allowedBindingIds,List<String> allowedClasses,List<String> excludedBindingIds){
        static final FlowConstraint NONE=new FlowConstraint(List.of(),List.of(),List.of(),List.of());
        FlowConstraint { allowedPools=allowedPools==null?List.of():List.copyOf(allowedPools);allowedBindingIds=allowedBindingIds==null?List.of():List.copyOf(allowedBindingIds);allowedClasses=allowedClasses==null?List.of():List.copyOf(allowedClasses);excludedBindingIds=excludedBindingIds==null?List.of():List.copyOf(excludedBindingIds); }
        boolean allows(Candidate c,String clazz){return !excludedBindingIds.contains(c.bindingId())&&(allowedBindingIds.isEmpty()||allowedBindingIds.contains(c.bindingId()))&&(allowedClasses.isEmpty()||allowedClasses.contains(clazz));}
    }
